CREATE TABLE IF NOT EXISTS official_travel_report (travel_id CHAR(36) PRIMARY KEY, summary TEXT NOT NULL, application TEXT NOT NULL, submitted_by_person_id CHAR(36) NOT NULL, submitted_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT official_travel_report_travel_fk FOREIGN KEY (travel_id) REFERENCES official_travel(id), CONSTRAINT official_travel_report_person_fk FOREIGN KEY (submitted_by_person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
